# Generated by manage.py generate_test_cases.
from collections.abc import Callable
from unittest.mock import patch

from django.core.exceptions import ValidationError
from django.http import HttpResponse
from django.test import override_settings
from django.urls import reverse

from bloomerp.communication.emails.email_providers import EmailProvider
from bloomerp.communication.emails.providers.imap_smtp import ImapSmtpAdapter
from bloomerp.communication.utils.crypto import is_encrypted_email_secret
from bloomerp.config.definition import BloomerpConfig
from bloomerp.models.communication.email_account import EmailAccount
from bloomerp.tests.base import (
    BloomerpModelViewTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestCreateEmailAccountView(BloomerpModelViewTestCase):
    """Verify the account wizard saves only after successful connection validation."""

    view_name = "add"
    model = EmailAccount

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover provider selection, verified creation, and failed SMTP/IMAP checks."""
        return [
            RequestScenario(
                name="Provider step shows only registered email providers",
                user=self.admin_user,
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text("IMAP / SMTP"),
                        self.does_not_contain_text("Google"),
                    ]
                ),
            ),
            self.creation_scenario(
                "SMTP and IMAP are verified before the account is saved"
            ),
            self.creation_scenario(
                "SMTP authentication failure keeps the settings and creates no account",
                self.reject_smtp_credentials,
                "SMTP authentication failed",
            ),
            self.creation_scenario(
                "SMTP timeout keeps the settings and creates no account",
                self.timeout_smtp,
                "SMTP server timed out",
            ),
            self.creation_scenario(
                "IMAP failure keeps the settings and creates no account",
                self.reject_imap_connection,
                "IMAP connection failed",
            ),
        ]

    def creation_scenario(
        self,
        name: str,
        failure_setup: Callable[[RequestScenario], None] | None = None,
        expected_error: str | None = None,
    ) -> RequestScenario:
        """Describe one account-creation request with isolated connection mocks."""
        preparation = [
            self.enable_email_secret,
            self.mock_connections,
            self.select_imap,
        ]
        if failure_setup is not None:
            preparation.append(failure_setup)
        validators = (
            [
                self.failed_creation_preserves_settings,
                self.contains_text(expected_error),
            ]
            if expected_error
            else self.imap_account_is_secure
        )
        return RequestScenario(
            name=name,
            method="POST",
            user=self.admin_user,
            data={
                "name": "Support",
                "email_address": "support@example.com",
                "username": "support@example.com",
                "password": "app-password",
                "imap_host": "imap.example.com",
                "imap_port": "993",
                "imap_security": EmailAccount.SecurityMode.SSL_TLS,
                "smtp_host": "smtp.example.com",
                "smtp_port": "587",
                "smtp_security": EmailAccount.SecurityMode.STARTTLS,
            },
            prepare=preparation,
            cleanup=[self.disable_email_secret, self.stop_connection_mock],
            expected=ExpectedResult(
                status_code=200 if expected_error else 302,
                response_validators=validators,
            ),
        )

    def enable_email_secret(self, _scenario: RequestScenario) -> None:
        """Configure credential encryption for the account-creation scenario."""
        self.settings_override = override_settings(
            BLOOMERP_CONFIG=BloomerpConfig(email_secret_key="test-secret")
        )
        self.settings_override.enable()

    def disable_email_secret(self, _scenario: RequestScenario) -> None:
        """Restore settings after the account-creation scenario."""
        self.settings_override.disable()

    def mock_connections(self, _scenario: RequestScenario) -> None:
        """Replace the adapter validation boundary with an unsaved-account check."""
        self.connection_patcher = patch.object(
            ImapSmtpAdapter,
            "validate_connection",
            autospec=True,
            side_effect=self.validate_unsaved_account,
        )
        self.connection_check = self.connection_patcher.start()

    def validate_unsaved_account(self, adapter: ImapSmtpAdapter) -> list[str]:
        """Ensure no account is saved or active while its connection is being tested."""
        account = adapter.email_account
        self.assertTrue(account._state.adding)
        self.assertEqual(account.status, EmailAccount.Status.DRAFT)
        self.assertFalse(
            EmailAccount.objects.filter(email_address=account.email_address).exists()
        )
        self.assertEqual(account.get_password_secret(), "app-password")
        return ["INBOX", "Sent"]

    def stop_connection_mock(self, _scenario: RequestScenario) -> None:
        """Restore adapter validation after each request scenario."""
        self.connection_patcher.stop()

    def select_imap(self, _scenario: RequestScenario) -> None:
        """Complete provider selection before submitting account connection details."""
        self.client.force_login(self.admin_user)
        response = self.client.post(
            reverse("email_accounts_add"),
            {"provider": EmailProvider.IMAP.value.key},
        )
        self.assertEqual(response.status_code, 200)

    def reject_smtp_credentials(self, _scenario: RequestScenario) -> None:
        """Make SMTP validation reject the submitted account credentials."""
        self.connection_check.side_effect = ValidationError(
            "SMTP authentication failed"
        )

    def timeout_smtp(self, _scenario: RequestScenario) -> None:
        """Make SMTP validation report a bounded connection timeout."""
        self.connection_check.side_effect = ValidationError("SMTP server timed out")

    def reject_imap_connection(self, _scenario: RequestScenario) -> None:
        """Make incoming-server validation fail after submission."""
        self.connection_check.side_effect = ValidationError("IMAP connection failed")

    def failed_creation_preserves_settings(self, response: HttpResponse) -> bool:
        """Check failed validation returns to configuration without saving an account."""
        self.connection_check.assert_called_once()
        context = response.context_data
        return (
            not EmailAccount.objects.filter(
                email_address="support@example.com"
            ).exists()
            and context["step_index"] == 1
            and context["form"].initial["email_address"] == "support@example.com"
            and context["form"].initial["smtp_host"] == "smtp.example.com"
            and context["form"].initial["imap_host"] == "imap.example.com"
        )

    def imap_account_is_secure(self, _response: HttpResponse) -> bool:
        """Check validated creation encrypts credentials and records ownership and mailboxes."""
        account = EmailAccount.objects.get(email_address="support@example.com")
        self.connection_check.assert_called_once()
        return (
            account.provider == EmailProvider.IMAP.value.key
            and account.status == EmailAccount.Status.ACTIVE
            and account.last_validated_at is not None
            and account.mailboxes == ["INBOX", "Sent"]
            and account.created_by == self.admin_user
            and account.imap_host == "imap.example.com"
            and account.smtp_host == "smtp.example.com"
            and account.password != "app-password"
            and is_encrypted_email_secret(account.password)
            and account.get_password_secret() == "app-password"
        )
